package com.aetherforge.config;
import com.aetherforge.security.BearerAuthFilter;import org.springframework.context.annotation.*;import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.web.*;import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;
@Configuration @EnableMethodSecurity public class SecurityConfig {@Bean SecurityFilterChain security(HttpSecurity http,BearerAuthFilter filter)throws Exception{http.csrf(c->c.disable()).cors(c->{}).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).headers(h->h.contentSecurityPolicy(c->c.policyDirectives("default-src 'self'; connect-src 'self' http://localhost:* ws://localhost:*; img-src 'self' data: blob:; style-src 'self' 'unsafe-inline'; script-src 'self'"))).authorizeHttpRequests(a->a.requestMatchers("/actuator/health/**","/swagger-ui/**","/swagger-ui.html","/v3/api-docs/**","/api/v1/auth/login","/api/v1/events").permitAll().anyRequest().authenticated()).addFilterBefore(filter,UsernamePasswordAuthenticationFilter.class);return http.build();}}
